INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Tract Anatomy','easy','flashcard','Name the five layers of the GI wall from outermost to innermost.','["Serosa \u2192 Longitudinal muscle \u2192 Circular muscle \u2192 Submucosa \u2192 Mucosa"]','A','The serosa is the outermost layer in intraperitoneal organs (replaced by adventitia in retroperitoneal segments). The two smooth muscle layers (longitudinal and circular) perform motility. The submucosa contains Meissner''s plexus and blood vessels. The mucosa faces the lumen.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Tract Anatomy','easy','flashcard','Where is Auerbach''s (myenteric) plexus located and what is its primary function?','["Between the circular and longitudinal smooth muscle layers; primary function is to control GI motility."]','A','Auerbach''s plexus regulates the intensity, rate, and velocity of peristaltic contractions. It contains both excitatory (cholinergic) and inhibitory (VIP/NO) neurons.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Tract Anatomy','medium','flashcard','What is the primary function of Meissner''s (submucosal) plexus?','["Controls local intestinal secretion, absorption, and submucosal muscle contraction."]','A','Meissner''s plexus lies within the submucosa. It receives sensory input from the epithelium and integrates signals to control secretion and local blood flow. It is distinct from Auerbach''s plexus, which controls motility.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Tract Anatomy','medium','flashcard','Which three main arteries supply the GI tract and what are their territories?','["Celiac artery (foregut: lower oesophagus to proximal duodenum, liver, pancreas, spleen); Superior mesenteric artery (midgut: distal duodenum to proximal 2/3 transverse colon); Inferior mesenteric artery (hindgut: distal transverse colon to upper rectum)."]','A','Knowledge of these vascular territories is essential for understanding ischaemic colitis (watershed areas at the splenic flexure), mesenteric ischaemia, and surgical planning.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Tract Anatomy','medium','flashcard','Which cells act as the electrical pacemakers of GI smooth muscle and where do they lie?','["Interstitial cells of Cajal (ICC), located between the smooth muscle layers (myenteric plexus region)."]','A','ICC generate slow-wave potentials (basic electrical rhythm): 3/min in stomach body, 12/min in duodenum, 8–9/min in terminal ileum. They are lost in Hirschsprung disease (which affects neurons, not ICC directly) and reduced in diabetic gastroparesis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Tract Anatomy','hard','flashcard','What spinal cord levels provide sympathetic innervation to the GI tract, and what is the general effect of sympathetic stimulation on gut function?','["Spinal segments T5\u2013L2; sympathetic stimulation generally inhibits GI motility and secretion (norepinephrine-mediated)."]','A','Preganglionic fibres synapse in prevertebral ganglia (celiac, superior mesenteric, inferior mesenteric). Norepinephrine inhibits enteric neurons and smooth muscle, reducing peristalsis and secretion. Sympathetics also constrict gut blood vessels and contract sphincters.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Tract Anatomy','easy','flashcard','What percentage of vagal fibres are afferent (sensory) versus efferent (motor)?','["Approximately 80% afferent (sensory), 20% efferent (motor)."]','A','The predominance of afferent vagal fibres highlights the importance of gut-to-brain signalling. These fibres transmit information about gut distension, chemical content, and mucosal integrity to the nucleus tractus solitarius in the medulla.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Tract Anatomy','hard','flashcard','Which sacral segments provide parasympathetic innervation to the distal GI tract and what reflex do they control?','["Sacral segments S2\u2013S4 via pelvic nerves; they control the defecation reflex."]','A','Sacral parasympathetics supply the distal half of the large intestine (descending colon, sigmoid, rectum) and anus. They coordinate the defecation reflex by causing colonic contraction and relaxation of the internal anal sphincter.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Tract Anatomy','medium','flashcard','Which layer of the GI wall is most important for bowel anastomotic strength?','["The submucosa \u2014 it contains dense collagen and elastin fibres providing tensile strength."]','A','The submucosa is the only layer that holds sutures reliably. Anastomotic leaks occur when this layer is inadequately incorporated. The mucosa and serosa add less structural strength.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Tract Anatomy','hard','flashcard','What is the slow-wave frequency in the body of the stomach, duodenum, and terminal ileum?','["Stomach body: ~3/min; Duodenum: ~12/min; Terminal ileum: ~8\u20139/min."]','A','The slow-wave (basic electrical rhythm) frequency is set by the ICC. These rates determine the maximum frequency of peristaltic contractions in each region. Slow waves alone do not cause contraction; spike potentials superimposed on slow-wave peaks trigger muscle contraction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Salivary Glands & Oesophagus','easy','flashcard','Which salivary gland produces purely serous saliva rich in amylase?','["The parotid gland."]','A','The parotid gland secretes serous saliva containing salivary amylase (ptyalin), IgA, and lysozyme. The submandibular gland secretes mixed serous and mucous saliva and provides the largest total resting volume (~65%). The sublingual gland secretes mainly mucous saliva.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 64'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Salivary Glands & Oesophagus','easy','flashcard','What are the three stages of swallowing and which one is voluntary?','["Oral (buccal) stage \u2014 voluntary; Pharyngeal stage \u2014 involuntary; Oesophageal stage \u2014 involuntary."]','A','The oral stage involves voluntary tongue movements to propel the bolus posteriorly. The pharyngeal and oesophageal stages are coordinated reflexively by the swallowing centre in the medulla oblongata (nucleus tractus solitarius and nucleus ambiguus).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 64'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Salivary Glands & Oesophagus','medium','flashcard','What is the normal resting pressure of the lower oesophageal sphincter (LOS)?','["15\u201325 mmHg above gastric pressure."]','A','The LOS maintains a zone of high pressure at the gastro-oesophageal junction, preventing acid reflux. In GORD, LOS pressure is typically < 10 mmHg. LOS tone is increased by gastrin, motilin, substance P, and alpha-adrenergic agonists; reduced by secretin, CCK, progesterone, nitrates, and calcium channel blockers.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 64'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Salivary Glands & Oesophagus','medium','flashcard','Which neurotransmitters mediate LOS relaxation during swallowing?','["Vasoactive intestinal polypeptide (VIP) and nitric oxide (NO), released from inhibitory myenteric neurons."]','A','Inhibitory motor neurons in the myenteric plexus of the distal oesophagus and LOS release VIP and NO to cause LOS relaxation during swallowing. Loss of these neurons (as in achalasia) results in failure of relaxation and functional oesophageal obstruction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 64'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Salivary Glands & Oesophagus','medium','flashcard','What is the difference between primary and secondary oesophageal peristalsis?','["Primary peristalsis: initiated by the act of swallowing; Secondary peristalsis: initiated by oesophageal distension without swallowing (clears retained bolus)."]','A','Secondary peristalsis is an intrinsic enteric nervous system reflex that helps clear the oesophagus of any material not propelled by primary peristalsis (e.g., refluxed gastric acid). It does not require central nervous system input.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 64'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Salivary Glands & Oesophagus','easy','flashcard','What is the main digestive function of saliva?','["Initiates carbohydrate digestion via salivary amylase (ptyalin), which hydrolyses starch into maltose and small glucose polymers."]','A','Salivary amylase is active in the mouth and continues working in the stomach until denatured by gastric acid. Saliva also lubricates food (mucins), provides antimicrobial protection (IgA, lysozyme), and buffers oral pH (bicarbonate).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 64'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Salivary Glands & Oesophagus','hard','flashcard','Describe the neural basis of achalasia.','["Degeneration of inhibitory myenteric plexus neurons (releasing nitric oxide and VIP) in the oesophageal body and LOS, causing failure of LOS relaxation and aperistalsis."]','A','In achalasia, selective loss of inhibitory (nitrergic and VIPergic) neurons leads to unopposed excitatory (cholinergic) tone, maintaining the LOS in a contracted state. Treatment includes pneumatic dilatation, Heller myotomy, or per-oral endoscopic myotomy (POEM).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 64'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Salivary Glands & Oesophagus','hard','flashcard','Which muscle forms the upper oesophageal sphincter (UOS) and what is its neural control?','["Cricopharyngeus muscle (part of inferior pharyngeal constrictor); controlled by somatic motor neurons via the pharyngeal branch of the vagus nerve."]','A','The UOS is composed of striated (skeletal) muscle, unlike the LOS which is smooth muscle. It maintains resting tone to prevent air entry and relaxes during swallowing (via somatic inhibitory motor neurons). It is not under voluntary control.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 64'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Salivary Glands & Oesophagus','hard','flashcard','What immunoglobulin predominates in saliva and how is it protected from proteolytic degradation?','["Secretory IgA (sIgA); protected by the secretory component (SC), a fragment of the polymeric immunoglobulin receptor added during transcytosis through epithelial cells."]','A','Lamina propria plasma cells produce dimeric IgA, which is transported across epithelial cells by the polymeric immunoglobulin receptor (pIgR). The extracellular portion of pIgR (secretory component) remains attached to sIgA and shields it from intestinal proteases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 64'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Salivary Glands & Oesophagus','medium','flashcard','During the pharyngeal stage of swallowing, what prevents nasal regurgitation and tracheal aspiration?','["Nasal regurgitation prevented by elevation of the soft palate; tracheal aspiration prevented by epiglottis closure over the larynx and approximation of the vocal cords."]','A','The pharyngeal stage is a complex reflex coordinated by the swallowing centre in the medulla. Respiration is briefly inhibited (deglutition apnoea). Failure of these protective mechanisms (e.g., in stroke) causes aspiration pneumonia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 64'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gastric Secretion','easy','flashcard','What two substances are secreted by gastric parietal cells?','["Hydrochloric acid (HCl) and intrinsic factor."]','A','Parietal cells in the gastric fundus and body contain the H+/K+-ATPase proton pump for HCl production and also secrete intrinsic factor essential for vitamin B12 absorption. Loss of parietal cells (autoimmune gastritis) causes both achlorhydria and pernicious anaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gastric Secretion','easy','flashcard','What is the role of pepsin in gastric digestion, and what is its precursor?','["Pepsin is a protease that initiates protein digestion; it is secreted as the inactive zymogen pepsinogen by chief (peptic) cells."]','A','Pepsinogen is converted to pepsin by HCl (pH < 2) and by autocatalytic action at pH 1.8–3.5. Pepsin is most active at very low pH and is inactivated at pH > 5. It begins protein hydrolysis but most protein digestion occurs in the small intestine via pancreatic proteases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gastric Secretion','medium','flashcard','Describe the three phases of gastric acid secretion and their approximate contributions.','["Cephalic phase (~20\u201330%): triggered by sight, smell, taste, or thought of food via vagal stimulation. Gastric phase (~60\u201370%): triggered by food entering the stomach (distension, protein products). Intestinal phase (~5\u201310%): triggered by amino acids and peptides in the duodenum."]','A','The cephalic phase is entirely neurally mediated (vagus nerve via ACh and GRP). The gastric phase involves both neural and hormonal stimulation (gastrin from G cells). The intestinal phase involves small amounts of gastrin from duodenal G cells.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gastric Secretion','medium','flashcard','What is the mechanism by which parietal cells secrete HCl?','["H+/K+-ATPase on the apical membrane actively secretes H+ into the lumen in exchange for K+. CO2 + H2O \u2192 H2CO3 (via carbonic anhydrase) \u2192 H+ + HCO3-. HCO3- exits via the basolateral Cl-/HCO3- exchanger (causing the ''alkaline tide'')."]','A','The H+/K+-ATPase (proton pump) maintains an intraluminal H+ concentration approximately 1,000,000-fold higher than plasma. Cl- is secreted via apical Cl- channels. This mechanism is the target of proton pump inhibitors (PPIs), which irreversibly bind the pump in its active state.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gastric Secretion','medium','flashcard','Which cell type is the intermediary between gastrin/vagal stimulation and parietal cell HCl secretion?','["Enterochromaffin-like (ECL) cells, which release histamine to act on H2 receptors on parietal cells."]','A','ECL cells in the gastric fundus are stimulated by gastrin (CCK-B receptors) and acetylcholine to release histamine. Histamine acts on H2 receptors on parietal cells, increasing cAMP and activating the proton pump. H2-receptor antagonists block this histamine-mediated step.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gastric Secretion','easy','flashcard','Intrinsic factor is required for absorption of which vitamin, and where is that vitamin absorbed?','["Vitamin B12 (cobalamin); absorbed in the terminal ileum."]','A','Intrinsic factor (IF) binds vitamin B12 in the stomach, protecting it from degradation. The IF-B12 complex binds the cubam receptor (cubilin-amnionless complex) on terminal ileal enterocytes and is internalised by endocytosis. IF is degraded intracellularly and B12 enters the portal circulation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gastric Secretion','hard','flashcard','What is the mechanism by which somatostatin inhibits gastric acid secretion?','["Somatostatin from D cells acts by: (1) directly inhibiting parietal cell H+/K+-ATPase via SSTR2/5 (reducing cAMP); and (2) paracrine inhibition of G cells (reducing gastrin release)."]','A','D cells in the antrum and fundus are stimulated by low pH (< 2) to release somatostatin in a paracrine fashion. This negative feedback loop prevents excessive acid secretion. Somatostatin also inhibits ECL cell histamine release. The term ''brake'' appropriately describes its multi-level inhibitory role.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gastric Secretion','hard','flashcard','Explain why autoimmune gastritis leads to both achlorhydria and pernicious anaemia.','["Autoimmune destruction of parietal cells eliminates both HCl production (causing achlorhydria) and intrinsic factor secretion, preventing vitamin B12 absorption (causing pernicious anaemia)."]','A','Anti-parietal cell antibodies and anti-intrinsic factor antibodies are characteristic. Without HCl, gastrin levels rise markedly (hypergastrinaemia) due to loss of pH-mediated feedback. Without intrinsic factor, B12 deficiency develops over years (B12 stores last 2–3 years), causing megaloblastic anaemia and subacute combined degeneration of the spinal cord.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gastric Secretion','hard','flashcard','What is the consequence of long-term PPI use on gastrin levels and ECL cells?','["Long-term PPI use raises gastric pH, removing pH-mediated inhibition of gastrin release \u2192 hypergastrinaemia \u2192 ECL cell hyperplasia (and rarely gastric carcinoid tumours)."]','A','PPIs irreversibly inhibit the active H+/K+-ATPase. Elevated pH → continuous G cell gastrin secretion → ECL cell stimulation and proliferation. This is generally reversible on stopping PPIs. Long-term use also risks hypomagnesaemia, increased risk of C. difficile infection, and impaired calcium absorption.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gastric Secretion','medium','flashcard','What stimulates and what inhibits gastrin release from antral G cells?','["Stimulants: protein digestion products (peptides/amino acids), gastric distension, vagal stimulation (via GRP), calcium. Inhibitors: low pH (< 2), somatostatin, secretin."]','A','Gastrin is the primary hormonal stimulus for gastric acid secretion. Gastrin also promotes gastric mucosal growth (trophic effect on oxyntic gland mucosa and ECL cells). The feedback inhibition by low pH is a key homeostatic mechanism preventing runaway acid hypersecretion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Pancreatic & Biliary Secretion','easy','flashcard','What is the primary hormone stimulating pancreatic enzyme secretion and which cells produce it?','["Cholecystokinin (CCK), produced by I cells of the duodenum and proximal jejunum in response to fats and proteins."]','A','CCK stimulates acinar cells to release digestive enzymes (proteases, lipases, amylase) and causes gallbladder contraction with sphincter of Oddi relaxation. CCK also inhibits gastric emptying and promotes satiety via vagal afferents.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Pancreatic & Biliary Secretion','easy','flashcard','What is the primary hormone stimulating pancreatic bicarbonate secretion and which cells produce it?','["Secretin, produced by S cells of the duodenum in response to luminal acid (pH < 4.5)."]','A','Secretin acts on pancreatic ductal cells to produce a high-volume, bicarbonate-rich (up to 120 mEq/L HCO3-) secretion that neutralises acid chyme in the duodenum. Secretin also inhibits gastric acid secretion and gastric emptying.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Pancreatic & Biliary Secretion','medium','flashcard','What is enterokinase and why is it physiologically critical?','["Enterokinase (enteropeptidase) is secreted by duodenal mucosal cells; it cleaves trypsinogen to active trypsin, initiating the pancreatic proteolytic activation cascade."]','A','Trypsin then activates all other pancreatic proenzymes (chymotrypsinogen, proelastase, procarboxypeptidase). Pancreatic trypsin inhibitor (PSTI) in pancreatic juice prevents premature intrapancreatic activation. Failure of this protection causes acute pancreatitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Pancreatic & Biliary Secretion','medium','flashcard','Name the two primary bile acids and their corresponding secondary bile acids.','["Cholic acid \u2192 Deoxycholic acid (7alpha-dehydroxylation by gut bacteria). Chenodeoxycholic acid \u2192 Lithocholic acid (7alpha-dehydroxylation by gut bacteria)."]','A','Primary bile acids are synthesised from cholesterol in the liver. Secondary bile acids are produced by colonic bacteria. Bile acids are conjugated with glycine or taurine in the liver before secretion into bile, increasing their solubility at intestinal pH.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Pancreatic & Biliary Secretion','medium','flashcard','What is colipase and why is it needed for fat digestion?','["Colipase is a pancreatic cofactor that anchors pancreatic lipase to the fat droplet surface and displaces inhibitory bile salts, enabling lipase to hydrolyse triglycerides."]','A','Without colipase, bile salts coating fat droplets physically displace pancreatic lipase. Colipase (activated from pro-colipase by trypsin) binds both lipase and the fat-water interface, allowing efficient lipolysis. Colipase deficiency causes fat malabsorption.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Pancreatic & Biliary Secretion','easy','flashcard','Where are bile salts reabsorbed and what is this process called?','["Terminal ileum (active reabsorption via ASBT); the process is called enterohepatic circulation."]','A','Approximately 95% of secreted bile salts are actively reabsorbed in the terminal ileum by the apical sodium-dependent bile acid transporter (ASBT). They travel via the portal circulation back to the liver for re-secretion. The bile salt pool cycles 2–3 times per meal and 6–8 times per day.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Pancreatic & Biliary Secretion','hard','flashcard','Describe the composition of bile and the role of each component.','["Bile contains: bile salts (emulsification/micelle formation), phospholipids (lecithin; stabilise cholesterol in solution), cholesterol (poorly soluble), bilirubin (excretory waste), water and electrolytes."]','A','Bile salts keep cholesterol and lecithin in mixed micelles. When cholesterol supersaturates bile (lithogenic bile), it precipitates to form cholesterol gallstones. Bilirubin is conjugated (direct) in hepatic bile; pigment stones form when unconjugated bilirubin precipitates (e.g., haemolytic states).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Pancreatic & Biliary Secretion','hard','flashcard','What is the ''alkaline tide'' following a meal and what causes it?','["A transient rise in blood (and urine) bicarbonate after a meal, caused by the basolateral secretion of HCO3- from parietal cells during HCl production."]','A','When parietal cells secrete H+ into the gastric lumen via H+/K+-ATPase, intracellular carbonic acid (H2CO3) dissociates to H+ (used for pumping) and HCO3-. The HCO3- exits via basolateral Cl-/HCO3- exchangers into the blood, causing transient postprandial alkalosis (alkaline tide).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Pancreatic & Biliary Secretion','medium','flashcard','By approximately how much does the gallbladder concentrate bile, and how?','["5\u201320 fold, by actively absorbing water and electrolytes (Na+, Cl-, HCO3-) while retaining bile salts, bilirubin, and cholesterol."]','A','Gallbladder epithelium has high water permeability. Active Na+ absorption creates an osmotic gradient driving water absorption. Concentration increases bile''s detergent potency. CCK-stimulated gallbladder contraction releases concentrated bile into the duodenum after a fatty meal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Pancreatic & Biliary Secretion','hard','flashcard','What complications arise if trypsinogen is prematurely activated within the pancreas?','["Acute pancreatitis: trypsin activates all other pancreatic proenzymes within the pancreas, causing autodigestion, inflammation, oedema, haemorrhage, and necrosis."]','A','Pancreatic acinar cells contain trypsin inhibitor (PSTI/SPINK1) as a protective mechanism. When this is overwhelmed (e.g., in gallstone pancreatitis, alcoholic pancreatitis, or PRSS1 mutations causing hereditary pancreatitis), intrapancreatic trypsin activation triggers the destructive enzyme cascade.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Intestinal Digestion & Absorption','easy','flashcard','Name the transporter responsible for luminal glucose uptake into enterocytes and its driving mechanism.','["SGLT1 (sodium-glucose linked transporter 1); driven by the inward Na+ electrochemical gradient (secondary active transport)."]','A','The Na+/K+-ATPase on the basolateral membrane maintains low intracellular Na+, creating the gradient that drives SGLT1. Glucose and galactose share this transporter. GLUT2 on the basolateral membrane then exports them to the bloodstream.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Intestinal Digestion & Absorption','easy','flashcard','How is fructose absorbed in the small intestine?','["By facilitated diffusion via GLUT5 on the apical membrane of enterocytes; exits via GLUT2 on the basolateral membrane."]','A','Unlike glucose and galactose (SGLT1-dependent), fructose absorption is passive and sodium-independent. High fructose intake can overwhelm GLUT5 capacity, leading to osmotic diarrhoea (fructose malabsorption). GLUT5 is also expressed in testis, kidney, and brain.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Intestinal Digestion & Absorption','medium','flashcard','Describe the pathway for dietary fat absorption from the intestinal lumen into the bloodstream.','["Fat emulsified by bile salts \u2192 hydrolysed by pancreatic lipase (+colipase) \u2192 fatty acids and monoglycerides incorporated into mixed micelles \u2192 passive diffusion into enterocytes \u2192 re-esterification to triglycerides \u2192 packaged into chylomicrons \u2192 secreted into lacteals \u2192 thoracic duct \u2192 left subclavian vein."]','A','Only long-chain fatty acids (>12 carbons) follow this lymphatic route. Short- and medium-chain fatty acids can be absorbed directly into portal blood without re-esterification. Chylomicrons carry apoB-48, apoA-I, apoC-II, and apoE; chylomicron triglycerides are hydrolysed by lipoprotein lipase in peripheral capillaries.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Intestinal Digestion & Absorption','medium','flashcard','Where and how is vitamin B12 absorbed?','["Terminal ileum; requires the intrinsic factor\u2013B12 complex to bind cubam receptors (cubilin-amnionless complex) on ileal enterocytes, then internalised by receptor-mediated endocytosis."]','A','Parietal cells secrete intrinsic factor (IF). IF binds B12 in the duodenum after release from R-proteins (haptocorrin). The IF-B12 complex resists proteolytic digestion and binds cubam receptors specifically in the terminal ileum. B12 is then transported to portal blood bound to transcobalamin II.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Intestinal Digestion & Absorption','easy','flashcard','Where is dietary iron primarily absorbed and what oxidation state is preferred?','["Duodenum and proximal jejunum; ferrous iron (Fe2+) is preferentially absorbed over ferric iron (Fe3+)."]','A','Fe3+ is reduced to Fe2+ by ferrireductase (Dcytb) on the brush border. Fe2+ is taken up by DMT1 (divalent metal transporter 1). Inside enterocytes, iron is stored as ferritin or exported via ferroportin on the basolateral membrane. Hepcidin downregulates ferroportin, reducing iron export in iron-replete states.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Intestinal Digestion & Absorption','medium','flashcard','What are the brush border disaccharidases and what do they produce?','["Maltase (maltose \u2192 2 glucose); Sucrase (sucrose \u2192 glucose + fructose); Lactase (lactose \u2192 glucose + galactose); Isomaltase (alpha-1,6 bonds in branched dextrins \u2192 glucose)."]','A','These enzymes are expressed on the microvilli of small intestinal enterocytes. Lactase deficiency (primary or secondary) is the most common disaccharidase deficiency worldwide, causing osmotic diarrhoea when lactose is consumed. Sucrase-isomaltase deficiency is a rare autosomal recessive condition.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Intestinal Digestion & Absorption','hard','flashcard','How are short-chain fatty acids (SCFAs) produced in the colon and what is their significance?','["SCFAs (acetate, propionate, butyrate) are produced by colonic bacterial fermentation of dietary fibre (resistant starch, non-digestible polysaccharides). Butyrate is the primary energy source for colonocytes; propionate reaches the liver; acetate enters systemic circulation."]','A','SCFAs provide ~5–10% of total caloric intake. Butyrate upregulates tight junction proteins, inhibits NF-kappaB (anti-inflammatory), and promotes apoptosis in cancer cells (anti-neoplastic). Reduced SCFA production (low-fibre diet) is associated with colorectal cancer and inflammatory bowel disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Intestinal Digestion & Absorption','hard','flashcard','Why do fat-soluble vitamins require bile salts for absorption?','["Fat-soluble vitamins (A, D, E, K) are lipophilic and cannot traverse the unstirred water layer adjacent to the enterocyte brush border without being incorporated into bile salt mixed micelles."]','A','Mixed micelles are amphipathic structures that solubilise lipophilic compounds and ferry them to the enterocyte surface, where they partition out and diffuse passively across the apical membrane. Conditions reducing bile salt availability (e.g., cholestasis, terminal ileal resection, bile acid sequestrants) cause fat-soluble vitamin deficiencies.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Intestinal Digestion & Absorption','hard','flashcard','What is the functional significance of intestinal villi and microvilli for absorption?','["Villi increase absorptive surface area ~10-fold over a flat sheet; microvilli (brush border) on each enterocyte increase it a further ~20-fold; together they provide a total absorptive area of approximately 200\u2013300 m2."]','A','The brush border also contains the digestive enzymes (disaccharidases, peptidases) and transport proteins (SGLT1, GLUT5, peptide transporters). Loss of villi (e.g., in coeliac disease, tropical sprue) dramatically reduces absorption, causing malabsorption syndrome.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Intestinal Digestion & Absorption','medium','flashcard','Which active vitamin D metabolite stimulates intestinal calcium absorption and by what mechanism?','["1,25-dihydroxyvitamin D (calcitriol); upregulates TRPV6 (apical calcium channel) and calbindin-D9k (intracellular calcium carrier) in duodenal enterocytes."]','A','Calcitriol is produced from 25-hydroxyvitamin D in the kidney by 1alpha-hydroxylase (stimulated by PTH and low calcium). It binds the vitamin D receptor (VDR) in enterocyte nuclei, transcriptionally upregulating TRPV6 and calbindin, increasing calcium absorption up to 4-fold.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Motility','easy','flashcard','What is the migrating motor complex (MMC) and what is its cycle length?','["The MMC is a cyclic pattern of GI motor activity during fasting that sweeps undigested material from the stomach and small intestine to the colon; cycle length ~90 minutes."]','A','The MMC has four phases: Phase I (quiescence), Phase II (irregular contractions), Phase III (regular high-amplitude contractions — the ''housekeeper wave''), Phase IV (transition). Motilin initiates Phase III. The MMC is abolished by eating.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Motility','easy','flashcard','Which hormone initiates phase III of the MMC?','["Motilin, released from M cells of the duodenum and jejunum during fasting."]','A','Motilin is secreted in a cyclic pattern during fasting, initiating the high-amplitude Phase III contractions every 90 minutes. Food intake suppresses motilin release and abolishes the MMC. Erythromycin (and its derivatives) are motilin receptor agonists used as prokinetics in gastroparesis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Motility','medium','flashcard','Describe the ''law of the intestine'' and which neurotransmitters mediate it.','["Intestinal distension causes excitation (contraction) orad (proximal) to the bolus and inhibition (relaxation) aborad (distal). Orad excitation: acetylcholine and substance P. Aborad inhibition: VIP and nitric oxide."]','A','This ascending excitation and descending inhibition pattern (Bayliss and Starling, 1899) is coordinated by the myenteric plexus and is the basis of propulsive peristalsis. It requires an intact enteric nervous system.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Motility','medium','flashcard','What is the gastrocolic reflex and what clinical relevance does it have?','["The gastrocolic reflex is an increase in colonic motility (mass movements) triggered by gastric and duodenal distension after a meal; clinically relevant as a cause of postprandial defecation urgency, especially in IBS."]','A','The gastrocolic reflex is mediated by both neural pathways (vagovagal and enteric reflexes) and hormones (CCK, gastrin). It explains the urge to defecate shortly after meals. It is exaggerated in irritable bowel syndrome with diarrhoea (IBS-D) and can be exploited therapeutically.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Motility','medium','flashcard','Describe haustral contractions of the colon and how they differ from mass movements.','["Haustral contractions: segmental, non-propulsive mixing contractions that facilitate water absorption; occur continuously. Mass movements: high-amplitude, propulsive contractions that move content over long distances; occur 3\u20134 times daily after meals."]','A','Haustral contractions retain colonic content, maximising contact time with the mucosa for water absorption (the colon absorbs up to 5–6 L/day). Mass movements (high-amplitude propagating contractions, HAPCs) sweep content from the transverse colon to the rectum and are triggered by the gastrocolic and duodenocolic reflexes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Motility','hard','flashcard','Explain the reflex mechanisms controlling the ileocaecal valve.','["Ileal distension or gastrin \u2192 relaxes the ileocaecal valve (allowing ileal contents into caecum). Caecal/colonic distension \u2192 increases ileocaecal sphincter tone (preventing backflow \u2014 colonoileal reflex)."]','A','The ileocaecal valve normally prevents backflow of bacteria-laden colonic contents into the sterile ileum. Ileal peristalsis propels content through the relaxed valve. Caecal distension triggers reflex closure. The valve is disrupted in right hemicolectomy, predisposing to small bowel bacterial overgrowth.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Motility','easy','flashcard','What is the basic electrical rhythm (slow-wave frequency) of the duodenum?','["Approximately 12 contractions per minute."]','A','The duodenum has the highest slow-wave frequency in the GI tract (~12/min), set by ICC in the myenteric plexus region. This frequency determines the maximum rate of peristaltic contractions. The stomach contracts at ~3/min and the terminal ileum at ~8–9/min.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Motility','hard','flashcard','What neural mechanism controls the defecation reflex?','["Rectal distension \u2192 intrinsic enteric reflexes + sacral parasympathetic reflexes (S2\u2013S4 via pelvic nerves) \u2192 internal anal sphincter relaxation (involuntary) + voluntary relaxation of external anal sphincter (pudendal nerve)."]','A','The internal anal sphincter (smooth muscle, involuntary) is relaxed by VIP and NO from inhibitory enteric neurons. The external anal sphincter (striated muscle, voluntary) is under somatic control via the pudendal nerve (S2–S4). Spinal cord injury above S2–S4 can cause reflex defecation; below S2–S4 causes constipation and overflow incontinence.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Motility','hard','flashcard','What is the enterogastric reflex and what stimuli trigger it?','["The enterogastric reflex inhibits gastric motility and acid secretion when the duodenum detects fat, acid (pH < 3.5), and hyperosmolality in the entering chyme."]','A','The enterogastric reflex is mediated by both enteric nervous system reflexes and hormones (secretin, CCK, GIP). It reduces gastric emptying rate, ensuring the duodenum is not overwhelmed by excess acid or hypertonic/hypotonic chyme that could damage its mucosa or impair digestion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Motility','medium','flashcard','What is the significance of the interstitial cells of Cajal in clinical disease?','["ICC loss or dysfunction causes motility disorders: reduced ICC are found in diabetic gastroparesis, Hirschsprung disease (mucosal ICC), and slow-transit constipation."]','A','In diabetic gastroparesis, hyperglycaemia and autonomic neuropathy reduce ICC numbers, impairing gastric slow-wave generation and causing delayed emptying. In Hirschsprung disease, the primary defect is absence of enteric neurons, but ICC are also affected secondarily in the aganglionic segment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Hormones','easy','flashcard','Where is gastrin secreted, what stimulates its release, and what are its main actions?','["Secreted by G cells of the gastric antrum. Stimulated by: protein digestion products, gastric distension, vagal stimulation (GRP). Main actions: stimulates HCl secretion (via ECL cell histamine), promotes gastric mucosal growth."]','A','Gastrin is the primary hormonal driver of gastric acid secretion. It also stimulates pepsinogen secretion, increases gastric motility, and has trophic effects on ECL cells and oxyntic gland mucosa. Inhibited by pH < 2 and somatostatin (negative feedback).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Hormones','easy','flashcard','Which cells secrete CCK, what stimulates its release, and what are its three main gastrointestinal actions?','["I cells of the duodenum and proximal jejunum; stimulated by fat and protein (amino acids). Main actions: (1) stimulates pancreatic enzyme secretion; (2) contracts gallbladder and relaxes sphincter of Oddi; (3) inhibits gastric emptying."]','A','CCK also acts on the vagus nerve to signal satiety to the hypothalamus. CCK-B receptors on parietal cells respond to gastrin (which shares structural homology with CCK). CCK is the major mediator of the postprandial pancreatic enzyme response.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Hormones','medium','flashcard','What is the incretin effect and which hormones mediate it?','["The incretin effect is the amplification of glucose-stimulated insulin secretion by gut hormones after oral glucose ingestion (vs. intravenous glucose). GIP (from K cells) and GLP-1 (from L cells) are the major incretins."]','A','The incretin effect accounts for approximately 50–70% of the insulin secretory response to an oral glucose load. GIP and GLP-1 act on pancreatic beta-cell GIP and GLP-1 receptors respectively, increasing cAMP and insulin secretion in a glucose-dependent manner. This effect is markedly reduced in type 2 diabetes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Hormones','medium','flashcard','What is the ''ileal brake'' and which hormones mediate it?','["The ileal brake is the inhibition of upper GI motility and secretion triggered by fat and nutrients reaching the distal ileum. Mediators: GLP-1, PYY, and neurotensin from L cells of the distal ileum."]','A','The ileal brake slows gastric emptying and small intestinal transit when nutrients (especially fat) are detected in the ileum, allowing more time for proximal digestion and absorption. GLP-1 and PYY also reduce appetite. The ileal brake is exaggerated after bariatric surgery (contributing to weight loss).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Hormones','medium','flashcard','Describe the location, stimulus, and main action of secretin.','["S cells of the duodenum; stimulated by acid (pH < 4.5) and fat; main action is to stimulate pancreatic ductal bicarbonate secretion, neutralising acid chyme."]','A','Secretin also stimulates biliary bicarbonate secretion, inhibits gastrin release and gastric acid secretion, and inhibits gastric motility. The pancreatic response to secretin can be tested clinically (secretin stimulation test) to assess exocrine pancreatic function.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Hormones','hard','flashcard','What is Zollinger-Ellison syndrome, what causes it, and how is it diagnosed?','["ZES is caused by a gastrinoma (gastrin-secreting tumour, usually in the pancreas or duodenum), causing hypergastrinaemia, gastric acid hypersecretion, and multiple recurrent peptic ulcers."]','A','Diagnosis: fasting serum gastrin > 1000 pg/mL with low gastric pH is virtually diagnostic. If gastrin is 100–1000 pg/mL, the secretin stimulation test is used: secretin normally inhibits gastrin, but in ZES it paradoxically stimulates a rise of > 200 pg/mL. Approximately 25% are associated with MEN1 syndrome.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Hormones','hard','flashcard','Describe the role of ghrelin in appetite regulation.','["Ghrelin is an orexigenic peptide secreted by X/A-like cells of the gastric fundus. Levels rise before meals (hunger signal) and fall after eating. It acts on hypothalamic NPY/AgRP neurons to stimulate food intake and on GH secretagogue receptors to stimulate GH release."]','A','Ghrelin is the only known circulating orexigenic gut hormone. It also promotes gastric emptying (prokinetic effect) and stimulates GH release from the pituitary. Ghrelin levels are low in obesity and rise after diet-induced weight loss (one mechanism of weight regain).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Hormones','hard','flashcard','What is the mechanism by which erythromycin is used as a prokinetic drug?','["Erythromycin and its derivatives act as motilin receptor agonists, mimicking motilin to trigger high-amplitude gastric and small intestinal contractions (phase III MMC-like activity)."]','A','Erythromycin is used in gastroparesis and to clear the stomach before emergency endoscopy (IV dose improves gastric visualisation). Tachyphylaxis (receptor downregulation) limits its long-term efficacy. It is not indicated for constipation as motilin receptors are sparse in the colon.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Hormones','easy','flashcard','CCK causes gallbladder contraction; what simultaneously happens to the sphincter of Oddi?','["The sphincter of Oddi relaxes, allowing bile to flow from the common bile duct into the duodenum."]','A','CCK coordinates gallbladder contraction with sphincter of Oddi relaxation to deliver concentrated bile into the duodenum after a fatty meal. Sphincter of Oddi dysfunction (SOD) causes biliary-type pain and elevated liver enzymes due to impaired bile flow.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Hormones','medium','flashcard','What are the key differences between GIP and GLP-1?','["GIP: from K cells (duodenum/jejunum), stimulated by glucose and fat, potentiates insulin, minimal effect on glucagon or gastric emptying. GLP-1: from L cells (ileum/colon), stimulated by fat/carbohydrates, potentiates insulin, inhibits glucagon, slows gastric emptying, reduces appetite, promotes beta-cell survival."]','A','Both are incretins inactivated by DPP-4. GLP-1 receptor agonists (e.g., semaglutide) are key T2DM and obesity drugs. GIP receptor agonism is also exploited in dual GIP/GLP-1 agonists (tirzepatide). GLP-1 is more clinically important due to its broader metabolic effects.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Liver Physiology','easy','flashcard','Name five major synthetic functions of the liver.','["Albumin synthesis; coagulation factor synthesis (I, II, V, VII, VIII, IX, X, XI, XIII); fibrinogen; bile acid synthesis from cholesterol; gluconeogenesis; lipoprotein synthesis (VLDL, HDL); urea synthesis."]','A','The liver is the principal synthetic organ in the body. Albumin (half-life ~20 days) is the main determinant of plasma oncotic pressure. Coagulation factors II, VII, IX, X require vitamin K. Loss of synthetic function (cirrhosis) leads to hypoalbuminaemia, coagulopathy, and hypoglycaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 70'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Liver Physiology','easy','flashcard','Which coagulation factors require vitamin K and why?','["Factors II (prothrombin), VII, IX, X, and proteins C and S. Vitamin K is required for gamma-carboxylation of glutamate residues, enabling Ca2+-mediated binding to phospholipid surfaces needed for clotting."]','A','Vitamin K-dependent factors are synthesised in the liver as inactive precursors. Gamma-carboxylation by vitamin K-dependent carboxylase adds a carboxyl group to specific glutamate residues, creating binding sites for calcium. Warfarin inhibits vitamin K epoxide reductase (VKORC1), reducing all vitamin K-dependent factors.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 70'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Liver Physiology','medium','flashcard','What is the half-life of albumin and what does a low serum albumin indicate?','["Half-life approximately 20 days; low serum albumin (hypoalbuminaemia) indicates chronic liver disease (reduced synthesis), malnutrition, nephrotic syndrome (loss), or protein-losing enteropathy."]','A','Because of its long half-life, serum albumin does not reflect acute changes in hepatic synthetic function. Prealbumin (transthyretin, half-life ~2 days) or PT/INR are better acute markers. Albumin provides ~80% of plasma oncotic pressure; hypoalbuminaemia < 25 g/L causes peripheral oedema and ascites.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 70'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Liver Physiology','medium','flashcard','How does the liver metabolise bilirubin?','["Unconjugated bilirubin (from haem breakdown) \u2192 transported bound to albumin \u2192 taken up by hepatocytes \u2192 conjugated with glucuronic acid (by UGT1A1) \u2192 water-soluble conjugated bilirubin \u2192 secreted into bile canaliculi \u2192 excreted in bile."]','A','In the gut, bacteria convert conjugated bilirubin to urobilinogen (partially reabsorbed, excreted in urine) and stercobilin (gives stool its brown colour). Jaundice occurs when serum bilirubin > 35 µmol/L (visible). Prehepatic jaundice: unconjugated predominates. Hepatic/posthepatic jaundice: conjugated predominates.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 70'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Liver Physiology','medium','flashcard','What is the enterohepatic circulation of bile acids?','["Bile acids secreted in bile \u2192 released into duodenum \u2192 facilitate fat digestion/absorption \u2192 95% actively reabsorbed in terminal ileum (ASBT) \u2192 portal blood \u2192 taken up by hepatocytes \u2192 re-secreted into bile."]','A','The bile acid pool (approximately 2–4 g total) cycles 6–8 times per day, supporting fat digestion at each meal. Only 5% (approximately 0.5 g/day) is lost in faeces and must be replaced by de novo synthesis from cholesterol. Interruption (terminal ileal disease or resection) causes bile acid diarrhoea and fat malabsorption.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 70'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Liver Physiology','hard','flashcard','Which cytochrome P450 enzyme metabolises the most drugs in the liver and what are its clinical implications?','["CYP3A4; it metabolises ~50% of all drugs. It is inducible (rifampicin, carbamazepine, phenytoin, St John''s wort \u2192 reduced drug levels) and inhibited (azole antifungals, macrolides, protease inhibitors, grapefruit juice \u2192 increased drug levels \u2192 toxicity)."]','A','CYP3A4 is the most abundant hepatic P450 and the major enzyme in intestinal wall drug metabolism (first-pass effect). Drug interactions via CYP3A4 are clinically common. For example, rifampicin induces CYP3A4, reducing plasma levels of tacrolimus, oral contraceptives, and many antiretrovirals.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 70'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Liver Physiology','hard','flashcard','Describe the function of hepatic Kupffer cells.','["Kupffer cells are liver-resident macrophages lining the hepatic sinusoids that phagocytose bacteria, cellular debris, endotoxin (LPS), and foreign particles arriving via the portal blood; they constitute ~80\u201390% of the body''s fixed macrophages."]','A','Kupffer cells also secrete cytokines (TNF-alpha, IL-1, IL-6) in response to LPS, mediating hepatic inflammation in alcoholic liver disease and NASH. They can be activated by gut-derived LPS (leaky gut) to promote systemic inflammation. In cirrhosis, dysfunctional Kupffer cells contribute to increased susceptibility to spontaneous bacterial peritonitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 70'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Liver Physiology','hard','flashcard','What is the role of hepatic stellate cells (Ito cells) in liver fibrosis?','["Normally store vitamin A in lipid droplets (quiescent). In chronic liver injury, activated by TGF-beta and other cytokines \u2192 transdifferentiate into myofibroblasts \u2192 produce excess collagen (types I and III) \u2192 hepatic fibrosis \u2192 cirrhosis."]','A','Hepatic stellate cell activation is the central mechanism of fibrosis in all forms of chronic liver disease (alcohol, NASH, viral hepatitis, autoimmune). Anti-fibrotic therapies target stellate cell activation, TGF-beta signalling, and collagen deposition. Resolution of fibrosis is possible in early stages if the underlying injury is removed.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 70'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Liver Physiology','hard','flashcard','Describe the urea cycle and its clinical relevance.','["The urea cycle (ornithine cycle) in periportal hepatocytes converts ammonia (from amino acid catabolism) to urea, which is excreted by the kidneys: NH3 + CO2 \u2192 carbamoyl phosphate \u2192 ornithine \u2192 citrulline \u2192 argininosuccinate \u2192 arginine \u2192 urea + ornithine."]','A','In hepatic failure, reduced urea cycle activity leads to hyperammonaemia, causing hepatic encephalopathy (astrocyte swelling, altered neurotransmission). Lactulose traps NH4+ in the colon; rifaximin reduces ammonia-producing gut bacteria. Urea cycle defects (e.g., OTC deficiency) cause neonatal hyperammonaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 70'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Liver Physiology','medium','flashcard','How does obstructive jaundice differ from haemolytic jaundice in terms of laboratory findings?','["Obstructive: conjugated bilirubin elevated, bilirubinuria present, urobilinogen absent in urine, pale stools, pruritus. Haemolytic: unconjugated bilirubin elevated, no bilirubinuria, urobilinogen increased in urine, dark stools."]','A','In obstructive jaundice, conjugated (water-soluble) bilirubin spills into urine (bilirubinuria, dark ''tea-coloured'' urine). Absence of bile in the intestine causes pale stools and fat malabsorption. In haemolytic jaundice, excessive bilirubin production exceeds hepatic conjugation capacity; unconjugated bilirubin cannot be filtered by the kidney.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 70'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Microbiome & Barrier Function','easy','flashcard','Which proteins form intestinal tight junctions and what is the clinical consequence of their disruption?','["Claudins and occludin (transmembrane proteins), scaffolded by ZO-1, ZO-2, ZO-3. Disruption causes increased intestinal permeability (''leaky gut''), allowing bacterial products (LPS, antigens) to translocate into the circulation."]','A','Claudin isoforms determine junctional selectivity (claudin-2 forms cation/water channels; claudin-4 and -8 are barrier-forming). Leaky gut is implicated in IBD, coeliac disease, metabolic endotoxaemia in obesity/NASH, and possibly autoimmune conditions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Microbiome & Barrier Function','easy','flashcard','Which cell type produces the protective mucus layer in the intestine and what is the principal mucin in the colon?','["Goblet cells; principal colonic mucin is MUC2."]','A','The colonic mucus layer has a two-layered structure: a firmly attached inner layer (bacteria-free, protective) and a loosely adherent outer layer (colonised by commensal bacteria). MUC2 is the structural backbone. Goblet cell dysfunction (e.g., reduced mucus in IBD) increases susceptibility to mucosal injury.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Microbiome & Barrier Function','medium','flashcard','What antimicrobial peptides do Paneth cells secrete and where are Paneth cells located?','["Paneth cells secrete alpha-defensins (cryptdins), lysozyme, phospholipase A2, and RegIIIgamma. They are located at the base of crypts of Lieberk\u00fchn, most numerous in the small intestine (especially ileum)."]','A','Paneth cell antimicrobial peptides maintain a sterile zone at the crypt base where intestinal stem cells (LGR5+ cells) reside, protecting them from bacterial infection. Paneth cell dysfunction (e.g., in Crohn''s disease, where defensin expression is reduced) may contribute to gut dysbiosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Microbiome & Barrier Function','medium','flashcard','Which two bacterial phyla dominate the healthy adult large intestine and what is their combined proportion?','["Firmicutes and Bacteroidetes; together they constitute approximately 90% of the colonic microbiome."]','A','Firmicutes include Lactobacillus, Clostridium, Ruminococcus, and Faecalibacterium prausnitzii (a key butyrate producer). Bacteroidetes include Bacteroides and Prevotella. The Firmicutes:Bacteroidetes ratio increases in obesity. Dysbiosis (altered microbiome composition) is associated with IBD, obesity, type 2 diabetes, and colorectal cancer.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Microbiome & Barrier Function','medium','flashcard','What is secretory IgA (sIgA) and how does it protect the gut mucosa?','["sIgA is dimeric IgA secreted by lamina propria plasma cells, transported across epithelial cells via pIgR, gaining a secretory component that protects it from proteolysis. It neutralises pathogens and prevents their adhesion to the mucosa (immune exclusion)."]','A','sIgA is the most abundant immunoglobulin in the body (approximately 3–5 g/day secreted into the gut lumen). It binds pathogens without activating complement, preventing inflammatory damage. It also helps maintain commensal microbiome composition by selectively binding potential pathogens.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Microbiome & Barrier Function','hard','flashcard','Describe the role of butyrate in colonocyte physiology.','["Butyrate is the primary energy source for colonocytes (~60\u201370% of energy needs), produced by bacterial fermentation of dietary fibre. It also upregulates tight junction proteins, inhibits NF-kappaB (anti-inflammatory), promotes goblet cell mucin secretion, and induces apoptosis in colorectal cancer cells."]','A','Butyrate also inhibits histone deacetylases (HDACs), regulating gene expression epigenetically. Low butyrate (from low-fibre diet or dysbiosis) is associated with colonocyte energy deficiency, increased permeability, mucosal inflammation, and colorectal cancer risk. Butyrate enemas are used in diversion colitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Microbiome & Barrier Function','hard','flashcard','Describe the toxins produced by Clostridium difficile and their mechanism of action.','["Toxin A (TcdA, enterotoxin) and Toxin B (TcdB, cytotoxin): both glucosylate and inactivate Rho GTPases (Rho, Rac, Cdc42), disrupting the actin cytoskeleton, destroying tight junctions, causing enterocyte apoptosis, and leading to pseudomembranous colitis."]','A','TcdB is approximately 1000-fold more potent than TcdA and is sufficient alone to cause disease. Some strains produce binary toxin (CDT), associated with more severe disease. Treatment: fidaxomicin (preferred) or vancomycin; bezlotoxumab (anti-TcdB monoclonal antibody) reduces recurrence. Faecal microbiota transplant (FMT) is highly effective for recurrent CDI.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Microbiome & Barrier Function','easy','flashcard','What are M cells and where are they found?','["M (microfold) cells are specialised follicle-associated epithelial cells overlying Peyer''s patches and isolated lymphoid follicles. They transcytose luminal antigens to underlying immune cells to initiate mucosal immune responses."]','A','M cells lack a mucus coat and have sparse, irregular microvilli (microfolds), facilitating antigen sampling. They transcytose both antigens and microorganisms (including pathogens such as Salmonella, Shigella, and poliovirus). This makes Peyer''s patches both immune surveillance sites and potential portals of entry for pathogens.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Microbiome & Barrier Function','hard','flashcard','How does gut microbiome dysbiosis contribute to metabolic endotoxaemia in obesity?','["Dysbiosis increases intestinal permeability (tight junction disruption) \u2192 translocation of bacterial LPS into portal circulation \u2192 LPS activates TLR4 on macrophages and adipocytes \u2192 NF-kappaB activation \u2192 TNF-alpha, IL-6, IL-1beta release \u2192 systemic low-grade inflammation \u2192 insulin resistance and NASH."]','A','Metabolic endotoxaemia (Cani et al., 2007) describes chronically elevated plasma LPS levels in obese individuals fed a high-fat diet. High-fat diets reduce Bifidobacterium (a bacterium that promotes tight junction integrity) and increase gram-negative bacteria, raising LPS burden. This mechanism links the gut microbiome to obesity and metabolic syndrome.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Microbiome & Barrier Function','medium','flashcard','What is the intestinal epithelial cell turnover time and which cells are responsible for renewal?','["Intestinal epithelial cells turn over every 3\u20135 days. Renewal is driven by LGR5+ intestinal stem cells located at the base of crypts of Lieberk\u00fchn."]','A','LGR5+ stem cells continuously self-renew and give rise to all intestinal epithelial cell types (enterocytes, goblet cells, enteroendocrine cells, tuft cells, and Paneth cells). The Wnt/beta-catenin signalling pathway is the primary driver of stem cell proliferation. Mutations in this pathway (APC gene) are the initiating event in colorectal cancer.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Regulation of Appetite & GI Reflexes','easy','flashcard','Where is the vomiting centre located and what inputs does it receive?','["Lateral reticular formation of the medulla oblongata. Inputs from: chemoreceptor trigger zone (CTZ/area postrema), vestibular apparatus (motion sickness), vagal afferents from GI tract, and higher cortical centres."]','A','The vomiting centre coordinates the entire vomiting act: retrograde giant contractions, LOS relaxation, diaphragm/abdominal muscle contraction. Antiemetics target different receptors: ondansetron (5-HT3 at CTZ/vagus), metoclopramide (D2 at CTZ), aprepitant (NK1 at vomiting centre), cyclizine (H1/muscarinic at vestibular/CTZ).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 72'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Regulation of Appetite & GI Reflexes','easy','flashcard','Why is the chemoreceptor trigger zone (CTZ) able to sense drugs and toxins in the blood?','["The CTZ (area postrema) lies in the floor of the fourth ventricle outside the blood-brain barrier, allowing circulating emetic agents (drugs, metabolic toxins, bacterial toxins) to directly stimulate its receptors."]','A','The CTZ contains dopamine (D2), serotonin (5-HT3), NK1, and histamine (H1) receptors. Emetic stimuli include opioids, cytotoxic chemotherapy, uraemic toxins, and pregnancy hormones. Being outside the BBB is essential to its function as a chemosensor for blood-borne emetic substances.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 72'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Regulation of Appetite & GI Reflexes','medium','flashcard','Describe the orexigenic hormone ghrelin: source, timing of release, and central mechanism of action.','["Source: X/A-like cells of the gastric fundal oxyntic glands. Release: rises before meals (hunger), falls after eating. Central mechanism: binds GHSR-1a receptors on NPY/AgRP neurons in the arcuate nucleus \u2192 stimulates NPY and AgRP release \u2192 increases food intake and reduces energy expenditure."]','A','Ghrelin is the only known circulating orexigenic gut hormone. It also stimulates GH release from the pituitary (GH secretagogue). Ghrelin levels are paradoxically low in obesity despite high fat mass and rise after diet-induced weight loss, contributing to weight regain. Post-gastric-sleeve surgery ghrelin levels fall dramatically.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 72'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Regulation of Appetite & GI Reflexes','medium','flashcard','Describe the actions of leptin on hypothalamic appetite circuits.','["Leptin (from adipose tissue) acts on arcuate nucleus neurons: inhibits NPY/AgRP (orexigenic) neurons \u2192 reduces appetite; activates POMC/CART (anorexigenic) neurons \u2192 increases satiety via alpha-MSH acting on MC4R."]','A','Leptin levels correlate with adipose tissue mass. In obesity, leptin resistance (impaired signal transduction despite high leptin levels) leads to hyperphagia. Rare congenital leptin deficiency (ob/ob mouse, or rare human mutations) causes severe early-onset obesity, reversed by leptin replacement.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 72'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Regulation of Appetite & GI Reflexes','medium','flashcard','What is a vagovagal reflex and give one example in GI physiology.','["A vagovagal reflex is a neural arc in which afferent vagal fibres transmit GI signals to the medulla, which then sends efferent vagal signals back to the GI tract to regulate its function. Example: gastric distension \u2192 vagal afferents \u2192 medulla \u2192 vagal efferents \u2192 increase gastric acid secretion and motility."]','A','Vagovagal reflexes require an intact vagus nerve. Vagotomy (now rarely performed surgically) abolishes cephalic phase and gastric phase acid secretion. Other vagovagal reflexes include oesophago-gastric relaxation (receptive relaxation of the stomach during swallowing) and the vomiting reflex.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 72'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Regulation of Appetite & GI Reflexes','hard','flashcard','Describe the sequence of events in the vomiting reflex.','["(1) Nausea + hypersalivation (parasympathetic); (2) retrograde giant contractions of small intestine sweep content into stomach; (3) LOS relaxation; (4) deep inspiration with glottis closed; (5) soft palate elevates; (6) synchronous contraction of diaphragm and abdominal muscles compresses stomach \u2192 gastric expulsion."]','A','This sequence is coordinated by the medullary vomiting centre. Retching involves rhythmic abdominal contractions without gastric expulsion (dry retching). Projectile vomiting (without nausea) suggests increased intracranial pressure directly stimulating the vomiting centre. Antiemetics act at different points in this reflex arc.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 72'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Regulation of Appetite & GI Reflexes','hard','flashcard','What is the dual-centre hypothesis of appetite control in the hypothalamus?','["The hypothalamus has two opposing centres: the lateral hypothalamic area (LHA, ''feeding centre'' \u2014 stimulation causes eating; destruction causes starvation) and the ventromedial hypothalamus (VMH, ''satiety centre'' \u2014 stimulation stops eating; destruction causes hyperphagia and obesity)."]','A','This classic model has been refined by the discovery of the arcuate nucleus (containing NPY/AgRP orexigenic neurons and POMC/CART anorexigenic neurons) and their modulation by peripheral hormones (ghrelin, leptin, insulin, PYY, GLP-1). The LHA contains orexin/hypocretin neurons regulating both appetite and arousal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 72'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Regulation of Appetite & GI Reflexes','easy','flashcard','What is the gastrocolic reflex and which populations experience it most strongly?','["The gastrocolic reflex is colonic mass movement triggered by gastric and duodenal distension after a meal; it is exaggerated in irritable bowel syndrome (IBS), particularly IBS-D."]','A','The reflex is mediated by both neural mechanisms (vagovagal and enteric reflexes) and hormones (gastrin, CCK). It is strongest in the morning (after overnight fasting and the first meal). Patients with IBS-D often feel urgency to defecate immediately after eating due to an exaggerated gastrocolic reflex.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 72'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Regulation of Appetite & GI Reflexes','hard','flashcard','Describe the role of NPY in appetite regulation and its interaction with ghrelin and leptin.','["NPY (neuropeptide Y), released from arcuate nucleus AgRP/NPY neurons, is one of the most potent orexigenic signals in the CNS. Ghrelin activates these neurons (increasing NPY/AgRP release); leptin inhibits them. NPY acts on Y1 and Y5 receptors in the hypothalamus to increase food intake and reduce energy expenditure."]','A','AgRP, co-released with NPY, is an endogenous antagonist of melanocortin-4 receptors (MC4R), blocking the anorexigenic effects of alpha-MSH (from POMC neurons). This dual mechanism (NPY excitatory + AgRP blocking anorexigenic tone) makes the NPY/AgRP system a powerful driver of appetite and potential therapeutic target for obesity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 72'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Regulation of Appetite & GI Reflexes','medium','flashcard','What stimulates and what inhibits ghrelin secretion?','["Stimulated by: fasting, hypoglycaemia, caloric restriction, sleep deprivation. Inhibited by: food ingestion (especially carbohydrates and fats), glucose, insulin, somatostatin."]','A','Ghrelin is the only known gut-derived circulating hormone that rises before meals and falls after eating, acting as a meal-initiation signal. It is also inhibited by Roux-en-Y gastric bypass surgery due to exclusion of the ghrelin-secreting fundus from contact with food, contributing to reduced hunger post-surgery.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 72');
